Context {SCFG_P : ScfgP}. Context {bmK : BMode}.   (* [comment removed for export] *)
Variable L : heap_layout.
Variable HI : heap_iface.
Variable P : PESK.sink_policy.
Hypothesis LY : PMU.layout L.
Hypothesis HIok : heap_iface_ok L SCFG HI.
Hypothesis KPM : hl_k_per_malloc L <= 1.
Hypothesis PMODE : PESK.sp_mode P.
Let KL := PECKU.klayout_U L LY.
Variable R0 : bvmap 5 word.
Variable M0 : word -> option byte.
Variable model0 : Model.
Variables (sp ptr ra : Z).
Variable payload : list byte.
Variable LB0 : list (Z * Z).
Variable cr0 : credit.
Variable g : PMST.st.
Hypothesis Hn : PECHU.n payload < 2 ^ 26.
Hypothesis Hcr0 : PMSP.credit_le (PECTU.TOPK, PECTU.TOPB0 + PESK.sp_B P) cr0.
Hypothesis Hgp : getr R0 (reg 3) = Z_to_bv 64 67584.
