Lemma stage4 :
  PMSP.syscat_spec RSEGS AD L HI -> PECSU.reader_read_spec L HI P ->
  forall (fx : FPState) R M model cr s s2 sm qc b K,
    PECHU.H3 L HI P R0 M0 model0 sp ra payload LB0 cr0 g R M model cr s s2 sm qc b -> K [] ->
    (forall (fx1 : FPState) R1 M1 model1 cr1 sm1 s' en k be nn,
        PECHU.H5 L HI P R0 M0 model0 sp ra payload LB0 cr0 g R1 M1 model1 cr1 s s2 sm1 s' en k be nn ->
        srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 0x34fb4 M1 model1) K) ->
    srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx R 0x34f94 M model) K.
Proof.
